import type { Redis } from 'ioredis'; import type { UrlRow } from '../modules/urls/url.repository.js'; export class UrlCache {constructor(private redis:Redis,private ttl:number){} private key(code:string){return `url:${code}`} async getUrl(code:string){try {const v=await this.redis.get(this.key(code)); return v?JSON.parse(v) as UrlRow:undefined}catch{return undefined}} async setUrl(url:UrlRow){try {await this.redis.set(this.key(url.shortCode),JSON.stringify(url),'EX',this.ttl)}catch{}} async deleteUrl(code:string){try {await this.redis.del(this.key(code))}catch{}}}
